package cn.richie696.component.secret.provider.pkcs11;
import cn.richie696.component.secret.bootstrap.*; import cn.richie696.component.secret.starter.SecretRuntimeAutoConfiguration; import org.springframework.boot.autoconfigure.*; import org.springframework.boot.autoconfigure.condition.*; import org.springframework.context.annotation.Bean;
@AutoConfiguration @AutoConfigureBefore(SecretRuntimeAutoConfiguration.class) @ConditionalOnProperty(prefix=BootstrapSecretProperties.PREFIX,name="enabled",havingValue="true") public class Pkcs11SecretAutoConfiguration { @Bean(destroyMethod="close") @ConditionalOnBean(SecretBootstrapState.class) @ConditionalOnMissingBean(Pkcs11SecretClient.class) Pkcs11SecretClient pkcs11SecretClient(SecretBootstrapState state){return state.topology().clients().values().stream().filter(Pkcs11SecretClient.class::isInstance).map(Pkcs11SecretClient.class::cast).findFirst().orElse(null);} }
